def draw_corner_pattern(draw):
    shapes = [
        [(756, 638), (826, 568), (896, 638)],
        [(826, 638), (896, 568), (966, 638)],
        [(896, 568), (966, 498), (1036, 568), (966, 638)],
        [(826, 498), (896, 428), (966, 498), (896, 568)],
        [(896, 428), (966, 358), (1036, 428), (966, 498)],
    ]

    for shape in shapes:
        draw.polygon(shape, fill=GRAY)

    for offset in [0, 72, 144]:
        draw.line(
            (760 + offset, 638, 1010, 388 + offset),
            fill=WHITE,
            width=10
        )

    for offset in [0, 72]:
        draw.line(
            (800 + offset, 638, 1010, 428 + offset),
            fill=WHITE,
            width=10
        )


# ============================================================
# CODE-BARRES DÉCORATIF FIXE
# ============================================================

def draw_design_barcode(draw, x=447, y=495, width=280, height=112):
    draw.rectangle(
        (x, y, x + width, y + height),
        fill=WHITE
    )

    seed = hashlib.sha256(
        DESIGN_BARCODE_VALUE.encode("utf-8")
    ).digest()

    cursor = x + 10
    usable_bottom = y + height - 7
    index = 0

    while cursor < x + width - 10:
        byte = seed[index % len(seed)]

        bar_width = 2 + (byte % 6)
        gap = 2 + ((byte // 7) % 4)

        draw.rectangle(
            (
                cursor,
                y + 7,
                min(cursor + bar_width, x + width - 10),
                usable_bottom
            ),
            fill=BLACK
        )

        cursor += bar_width + gap
        index += 1


# ============================================================
# QR CODE
# ============================================================

def make_qr(url, size=300):
    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_H,
        box_size=10,
        border=4
    )

    qr.add_data(url)
    qr.make(fit=True)

    img = qr.make_image(
        fill_color="black",
        back_color="white"
    ).convert("RGB")

    return ImageOps.contain(
        img,
        (size, size),
        method=Image.Resampling.NEAREST
    )


