# ============================================================
# APOGÉE / ORACLE — THICK MODE OBLIGATOIRE
# ============================================================

# Valeurs réseau proposées par défaut d'après le prototype fourni.
# Le LOGIN et le MOT DE PASSE ne sont PAS enregistrés dans le code :
# ils sont demandés dans l'interface Streamlit.
DEFAULT_APOGEE_HOST = "172.16.1.104"
DEFAULT_APOGEE_PORT = 15211
DEFAULT_APOGEE_SERVICE = "PROD"

# Dossier photo local demandé.
DEFAULT_IMAGE_DIR = r"C:\myimage"


def get_python_architecture():
    import struct as _struct
    return _struct.calcsize("P") * 8


def get_pe_architecture(dll_path):
    """
    Lit l'en-tête PE de oci.dll sans charger la DLL.
    Retourne 32, 64 ou None.
    """
    try:
        dll_path = Path(dll_path)

        with dll_path.open("rb") as f:
            if f.read(2) != b"MZ":
                return None

            f.seek(0x3C)
            pe_offset = struct.unpack("<I", f.read(4))[0]
            f.seek(pe_offset)

            if f.read(4) != b"PE\x00\x00":
                return None

            machine = struct.unpack("<H", f.read(2))[0]

        if machine == 0x014C:   # x86
            return 32

        if machine in (0x8664, 0xAA64):  # AMD64 / ARM64
            return 64

        return None

    except Exception:
        return None


def oracle_client_architecture(client_dir):
    if not client_dir:
        return None

    p = Path(client_dir) / "oci.dll"

    if not p.exists():
        return None

    return get_pe_architecture(p)


def discover_oracle_clients():
    candidates = []
    seen = set()

    def add_candidate(folder):
        try:
            folder = str(folder or "").strip().strip('"')

            if not folder:
                return

            p = Path(folder)

            if p.is_dir() and (p / "oci.dll").exists():
                value = str(p)
                key = value.lower() if os.name == "nt" else value

                if key not in seen:
                    seen.add(key)
                    candidates.append(value)
        except Exception:
            pass

    add_candidate(
        os.getenv(
            "ORACLE_CLIENT_LIB_DIR",
            ""
        )
    )

    if os.name == "nt":
        for raw in os.environ.get("PATH", "").split(";"):
            add_candidate(raw)

        patterns = [
            r"C:\oracle\instantclient_*",
            r"C:\instantclient_*",
            r"C:\Oracle\instantclient_*",
            r"C:\orant\bin",
            r"C:\app\*\product\*\client_*\bin",
            r"C:\app\*\product\*\dbhome_*\bin",
        ]

        for pattern in patterns:
            try:
                for match in glob.glob(pattern):
                    add_candidate(match)
            except Exception:
                pass

    return candidates


def detect_oracle_client_dir():
    """
    Sélectionne automatiquement un Oracle Client de même architecture
    que Python.
    """
    python_arch = get_python_architecture()

    for client_dir in discover_oracle_clients():
        if oracle_client_architecture(client_dir) == python_arch:
            return client_dir

    return ""


def init_oracle_client_thick(client_lib_dir):
    """
    Initialise python-oracledb en Thick mode avec contrôle 32/64-bit.
    """
    try:
        import oracledb
    except ImportError:
        raise RuntimeError(
            "Le module 'oracledb' n'est pas installé.\\n"
            "Exécutez : pip install oracledb"
        )

    client_lib_dir = str(
        client_lib_dir or ""
    ).strip()

    python_arch = get_python_architecture()

    if not client_lib_dir:
        discovered = discover_oracle_clients()

        details = []

        for folder in discovered:
            details.append(
                f"- {folder} : {oracle_client_architecture(folder) or '?'}-bit"
            )

        extra = (
            "\\n\\nClients Oracle trouvés :\\n"
            + "\\n".join(details)
            if details
            else
            "\\n\\nAucun oci.dll n'a été trouvé automatiquement."
        )

        raise RuntimeError(
            f"Oracle Instant Client {python_arch}-bit requis.\\n"
            "Renseignez le dossier contenant oci.dll."
            + extra
        )

    p = Path(client_lib_dir)

    if not p.is_dir():
        raise RuntimeError(
            "Le dossier Oracle Client n'existe pas :\\n"
            + client_lib_dir
        )

    oci_path = p / "oci.dll"

    if not oci_path.exists():
        raise RuntimeError(
            "oci.dll n'a pas été trouvé dans :\\n"
            + client_lib_dir
        )

    client_arch = get_pe_architecture(oci_path)

    if client_arch and client_arch != python_arch:
        matching = []

        for folder in discover_oracle_clients():
            if oracle_client_architecture(folder) == python_arch:
                matching.append(folder)

        matching_text = (
            "\\n\\nClient(s) compatible(s) détecté(s) :\\n- "
            + "\\n- ".join(matching)
            if matching
            else
            ""
        )

        raise RuntimeError(
            "Architecture Oracle Client incompatible.\\n\\n"
            f"Python : {python_arch}-bit\\n"
            f"Oracle Client : {client_arch}-bit\\n"
            f"OCI : {oci_path}\\n\\n"
            "Les architectures doivent être identiques.\\n"
            "Si C:\\\\orant\\\\bin est 32-bit et Python est 64-bit, "
            "utilisez un Oracle Instant Client 64-bit compatible avec "
            "votre serveur Apogée, ou exécutez toute l'application avec "
            "un Python 32-bit."
            + matching_text
        )

    if os.name == "nt":
        current_path = os.environ.get(
            "PATH",
            ""
        )

        if client_lib_dir.lower() not in current_path.lower():
            os.environ["PATH"] = (
                client_lib_dir
                + ";"
                + current_path
            )

    try:
        if not oracledb.is_thin_mode():
            return oracledb
    except Exception:
        pass

    try:
        oracledb.init_oracle_client(
            lib_dir=client_lib_dir
        )

    except Exception as error:
        raise RuntimeError(
            "Impossible d'initialiser Oracle Client en Thick mode.\\n\\n"
            f"Python : {python_arch}-bit\\n"
            f"Oracle Client : {client_arch or '?'}-bit\\n"
            f"ORACLE_CLIENT_LIB_DIR = {client_lib_dir}\\n\\n"
            f"Détail : {error}"
        )

    if oracledb.is_thin_mode():
        raise RuntimeError(
            "python-oracledb est encore en Thin mode.\\n"
            "Redémarrez complètement Streamlit après avoir "
            "configuré le client Oracle compatible."
        )

    return oracledb


def make_apogee_dsn(
    oracledb,
    host,
    port,
    service
):
    return oracledb.makedsn(
        str(host).strip(),
        int(port),
        service_name=str(service).strip()
    )


def create_apogee_pool(
    host,
    port,
    service,
    user,
    password,
    client_lib_dir
):
    """
    Reprend la logique fournie :
      init Oracle Client -> make_dsn -> create_pool -> test acquire.
    """
    user = str(
        user or ""
    ).strip()

    password = str(
        password or ""
    )

    if not user:
        raise ValueError(
            "Saisissez l'utilisateur Oracle."
        )

    if not password:
        raise ValueError(
            "Saisissez le mot de passe Oracle."
        )

    oracledb = init_oracle_client_thick(
        client_lib_dir
    )

    dsn = make_apogee_dsn(
        oracledb=oracledb,
        host=host,
        port=port,
        service=service
    )

    try:
        pool = oracledb.create_pool(
            user=user,
            password=password,
            dsn=dsn,
            min=1,
            max=4,
            increment=1,
            getmode=oracledb.POOL_GETMODE_WAIT
        )

        # Test réel de connexion.
        with pool.acquire() as conn:
            cur = conn.cursor()
            try:
                cur.execute(
                    "SELECT 1 FROM DUAL"
                )
                cur.fetchone()
            finally:
                cur.close()

        return pool

    except Exception as error:
        raise RuntimeError(
            "Connexion Apogée impossible en Thick mode.\n\n"
            f"Hôte : {host}\n"
            f"Port : {port}\n"
            f"Service : {service}\n\n"
            f"Détail : {error}"
        )


def close_apogee_pool(pool):
    try:
        if pool is not None:
            pool.close()
    except Exception:
        pass


def build_ident_filter(
    valeur,
    table_alias="i"
):
    """
    Même logique que le code fourni :
      - uniquement des chiffres -> Code Apogée (COD_ETU)
      - sinon -> CIN en MAJUSCULE
    """
    v = str(
        valeur or ""
    ).strip().upper()

    if not v:
        return None, {}

    if v.isdigit():
        return (
            f"{table_alias}.COD_ETU = :code_etu",
            {
                "code_etu": int(v)
            }
        )

    return (
        f"UPPER(TRIM({table_alias}.CIN_IND)) = :cin",
        {
            "cin": v
        }
    )


def find_student_photo_by_cin(
    cin,
    image_dir
):
    """
    Recherche la photo dans le dossier local par CIN EN MAJUSCULE.

    Exemples :
      C:\\myimage\\BK756677.jpg
      C:\\myimage\\BK756677.JPG
      C:\\myimage\\BK756677.png
      C:\\myimage\\BK756677.jpeg

    Retour :
      (PIL.Image | None, chemin | None)
    """
    cin_upper = str(
        cin or ""
    ).strip().upper()

    if not cin_upper:
        return None, None

    root = Path(
        str(image_dir or "").strip()
    )

    if not root.is_dir():
        return None, None

    allowed = {
        ".jpg",
        ".jpeg",
        ".png",
        ".bmp",
        ".webp"
    }

    # Recherche insensible à la casse.
    try:
        for file_path in root.iterdir():
            if not file_path.is_file():
                continue

            if file_path.suffix.lower() not in allowed:
                continue

            if file_path.stem.strip().upper() != cin_upper:
                continue

            try:
                return (
                    Image.open(
                        file_path
                    ).convert("RGB"),
                    str(file_path)
                )
            except Exception:
                continue

    except Exception:
        pass

    return None, None


def fetch_student_from_apogee(
    pool,
    ident_value,
    image_dir
):
    """
    Recherche UNE personne par :
      - Code Apogée
      - CIN

    Informations de base depuis INDIVIDU :
      COD_ETU, NOM, PRENOM, CIN, COD_NNE_IND(CNE)

    Puis dernière inscription active depuis :
      INS_ADM_ETP + DIPLOME + ETAPE

    Photo :
      C:\\myimage\\<CIN_MAJUSCULE>.<extension>
    """
    ident_filter, binds = build_ident_filter(
        ident_value,
        table_alias="i"
    )

    if not ident_filter:
        raise ValueError(
            "Saisissez un Code Apogée ou un CIN."
        )

    # --------------------------------------------------------
    # 1) INDIVIDU
    # --------------------------------------------------------
    sql_student = f"""
        SELECT
            i.COD_IND          AS COD_IND,
            i.COD_ETU          AS APOGEE,
            i.LIB_NOM_PAT_IND  AS NOM,
            i.LIB_PR1_IND      AS PRENOM,
            i.CIN_IND          AS CIN,
            i.COD_NNE_IND      AS CNE
        FROM INDIVIDU i
        WHERE {ident_filter}
          AND ROWNUM = 1
    """

    with pool.acquire() as conn:
        cur = conn.cursor()

        try:
            cur.execute(
                sql_student,
                binds
            )

            row = cur.fetchone()

            if not row:
                raise LookupError(
                    "Aucun étudiant trouvé avec cet identifiant."
                )

            columns = [
                c[0].upper()
                for c in cur.description
            ]

            student_row = dict(
                zip(
                    columns,
                    row
                )
            )

        finally:
            cur.close()

        # ----------------------------------------------------
        # 2) DERNIÈRE INSCRIPTION ACTIVE
        # ----------------------------------------------------
        sql_inscription = """
            SELECT *
            FROM (
                SELECT
                    iae.COD_DIP      AS CODE_DIPLOME,
                    d.LIB_DIP        AS NOM_DIPLOME,
                    iae.COD_ETP      AS CODE_ETAPE,
                    etp.LIB_ETP      AS NOM_ETAPE,
                    iae.COD_ANU      AS ANNEE_INSCRIPTION
                FROM INS_ADM_ETP iae
                LEFT JOIN DIPLOME d
                    ON iae.COD_DIP = d.COD_DIP
                LEFT JOIN ETAPE etp
                    ON iae.COD_ETP = etp.COD_ETP
                WHERE iae.COD_IND = :cod_ind
                  AND iae.ETA_IAE = 'E'
                ORDER BY iae.COD_ANU DESC
            )
            WHERE ROWNUM = 1
        """

        inscription = {}

        cur = conn.cursor()

        try:
            cur.execute(
                sql_inscription,
                {
                    "cod_ind": student_row.get(
                        "COD_IND"
                    )
                }
            )

            row = cur.fetchone()

            if row:
                columns = [
                    c[0].upper()
                    for c in cur.description
                ]

                inscription = dict(
                    zip(
                        columns,
                        row
                    )
                )

        finally:
            cur.close()

    cin = str(
        student_row.get("CIN") or ""
    ).strip().upper()

    photo, photo_path = find_student_photo_by_cin(
        cin=cin,
        image_dir=image_dir
    )

    # Pour le champ "Filière" de la carte :
    # nom de l'étape en priorité, sinon code étape,
    # sinon diplôme.
    filiere = (
        inscription.get("NOM_ETAPE")
        or inscription.get("CODE_ETAPE")
        or inscription.get("NOM_DIPLOME")
        or ""
    )

    return {
        "numero": str(
            student_row.get("APOGEE") or ""
        ).strip(),
        "cne": str(
            student_row.get("CNE") or ""
        ).strip(),
        "cin": cin,
        "nom": str(
            student_row.get("NOM") or ""
        ).strip(),
        "prenom": str(
            student_row.get("PRENOM") or ""
        ).strip(),
        "filiere": str(
            filiere or ""
        ).strip(),
        "code_etape": str(
            inscription.get("CODE_ETAPE") or ""
        ).strip(),
        "nom_etape": str(
            inscription.get("NOM_ETAPE") or ""
        ).strip(),
        "code_diplome": str(
            inscription.get("CODE_DIPLOME") or ""
        ).strip(),
        "nom_diplome": str(
            inscription.get("NOM_DIPLOME") or ""
        ).strip(),
        "annee": str(
            inscription.get("ANNEE_INSCRIPTION") or ""
        ).strip(),
        "photo": photo,
        "photo_path": photo_path,
    }


# ============================================================
# DÉTECTION DES IMPRIMANTES WINDOWS
# ============================================================

def _clean_printer_names(names):
    result = []

    for name in names:
        if name:
            value = str(name).strip()

            if value and value not in result:
                result.append(value)

    return result


def list_printers_pywin32():
    names = []

    if os.name != "nt":
        return names

    try:
        import win32print

        # Locales + connexions
        flags = (
            win32print.PRINTER_ENUM_LOCAL
            |
            win32print.PRINTER_ENUM_CONNECTIONS
        )

        for p in win32print.EnumPrinters(flags):
            if len(p) > 2:
                names.append(p[2])

        # Imprimante par défaut
        try:
            default_printer = win32print.GetDefaultPrinter()
            names.append(default_printer)
        except Exception:
            pass

    except Exception:
        pass

    return _clean_printer_names(names)


def list_printers_powershell():
    names = []

    if os.name != "nt":
        return names

    try:
        command = [
            "powershell.exe",
            "-NoProfile",
            "-Command",
            "Get-Printer | Select-Object -ExpandProperty Name"
        ]

        completed = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=8,
            creationflags=getattr(
                subprocess,
                "CREATE_NO_WINDOW",
                0
            )
        )

        if completed.returncode == 0:
            names.extend(
                line.strip()
                for line in completed.stdout.splitlines()
                if line.strip()
            )

    except Exception:
        pass

    return _clean_printer_names(names)


def list_printers_wmic():
    names = []

    if os.name != "nt":
        return names

    try:
        completed = subprocess.run(
            [
                "wmic",
                "printer",
                "get",
                "name"
            ],
            capture_output=True,
            text=True,
            timeout=8,
            creationflags=getattr(
                subprocess,
                "CREATE_NO_WINDOW",
                0
            )
        )

        if completed.returncode == 0:
            lines = [
                x.strip()
                for x in completed.stdout.splitlines()
                if x.strip()
            ]

            for line in lines:
                if line.lower() != "name":
                    names.append(line)

    except Exception:
        pass

    return _clean_printer_names(names)


def list_windows_printers():
    """
    Essaie plusieurs méthodes pour maximiser la détection.
    """

    all_names = []

    all_names.extend(
        list_printers_pywin32()
    )

    all_names.extend(
        list_printers_powershell()
    )

    all_names.extend(
        list_printers_wmic()
    )

    names = _clean_printer_names(
        all_names
    )

    # Evolis en premier dans la liste.
    evolis = [
        p
        for p in names
        if "evolis" in p.lower()
    ]

    others = [
        p
        for p in names
        if p not in evolis
    ]

    return evolis + others


def get_default_windows_printer():
    if os.name != "nt":
        return None

    try:
        import win32print
        return win32print.GetDefaultPrinter()
    except Exception:
        return None


# ============================================================
# EVOLIS — ETAT, DUPLEX, FILE D'ATTENTE, IMPRESSION PLEINE CARTE
# ============================================================

# Windows printer status flags.
PRINTER_STATUS_FLAGS = {
    0x00000001: "PAUSE",
    0x00000002: "ERREUR",
    0x00000004: "SUPPRESSION_EN_COURS",
    0x00000008: "CARTE_BLOQUEE / PAPER_JAM",
    0x00000010: "PLUS_DE_CARTES / PAPER_OUT",
    0x00000020: "ALIMENTATION_MANUELLE",
    0x00000040: "PROBLEME_SUPPORT",
    0x00000080: "HORS_LIGNE",
    0x00000100: "IO_ACTIVE",
    0x00000200: "OCCUPEE",
    0x00000400: "IMPRESSION_EN_COURS",
    0x00000800: "BAC_SORTIE_PLEIN",
    0x00001000: "NON_DISPONIBLE",
    0x00002000: "EN_ATTENTE",
    0x00004000: "TRAITEMENT_EN_COURS",
    0x00008000: "INITIALISATION",
    0x00010000: "CHAUFFE",
    0x00020000: "CONSOMMABLE_BAS",
    0x00040000: "CONSOMMABLE_VIDE",
    0x00080000: "PAGE_REJETEE",
    0x00100000: "INTERVENTION_UTILISATEUR",
    0x00200000: "MEMOIRE_INSUFFISANTE",
    0x00400000: "CAPOT_OUVERT",
    0x00800000: "SERVEUR_INCONNU",
    0x01000000: "ECONOMIE_ENERGIE",
}

BUSY_FLAGS = (
    0x00000100 |  # IO_ACTIVE
    0x00000200 |  # BUSY
    0x00000400 |  # PRINTING
    0x00002000 |  # WAITING
    0x00004000 |  # PROCESSING
    0x00008000 |  # INITIALIZING
    0x00010000    # WARMING_UP
)

ERROR_FLAGS = (
    0x00000001 |  # PAUSED
    0x00000002 |  # ERROR
    0x00000004 |  # PENDING_DELETION
    0x00000008 |  # PAPER_JAM
    0x00000010 |  # PAPER_OUT
    0x00000020 |  # MANUAL_FEED
    0x00000040 |  # PAPER_PROBLEM
    0x00000080 |  # OFFLINE
    0x00000800 |  # OUTPUT_BIN_FULL
    0x00001000 |  # NOT_AVAILABLE
    0x00040000 |  # NO_TONER / consumable empty
    0x00080000 |  # PAGE_PUNT
    0x00100000 |  # USER_INTERVENTION
    0x00200000 |  # OUT_OF_MEMORY
    0x00400000    # DOOR_OPEN
)

CR80_RATIO = 85.60 / 53.98


def decode_printer_status(status):
    labels = []

    for flag, label in PRINTER_STATUS_FLAGS.items():
        if status & flag:
            labels.append(label)

    if not labels:
        labels.append("PRETE / AUCUN DRAPEAU WINDOWS")

    return labels


def inspect_printer(printer_name, duplex_edge="short"):
    """
    Pré-vérification CONSERVATRICE avant toute impression.

    Vérifie :
      1) l'imprimante existe ;
      2) l'état Windows : prête / occupée / erreur ;
      3) la file d'attente est vide ;
      4) Windows annonce une capacité duplex ;
      5) le DEVMODE accepte vraiment un mode duplex ;
      6) les informations pilote/port sont accessibles.

    Si un point critique échoue, ready_for_duplex=False.
    Le bouton d'impression doit alors BLOQUER.
    """

    result = {
        "printer": printer_name,
        "exists": False,
        "driver_name": "",
        "port_name": "",
        "status_value": 0,
        "status_labels": [],
        "queue_jobs": 0,
        "jobs": [],
        "busy": False,
        "error": False,
        "duplex_capability": False,
        "duplex_devmode_accepted": False,
        "ready_for_duplex": False,
        "message": "",
    }

    if os.name != "nt":
        result["message"] = (
            "Le contrôle Evolis doit être exécuté sous Windows."
        )
        return result

    try:
        import win32print
        import win32con
    except ImportError:
        result["message"] = (
            "pywin32 n'est pas installé. "
            "Exécutez : pip install pywin32"
        )
        return result

    hprinter = None

    try:
        hprinter = win32print.OpenPrinter(printer_name)
        result["exists"] = True

        info = win32print.GetPrinter(hprinter, 2)

        result["driver_name"] = str(
            info.get("pDriverName") or ""
        )

        result["port_name"] = str(
            info.get("pPortName") or ""
        )

        status = int(
            info.get("Status") or 0
        )

        result["status_value"] = status
        result["status_labels"] = decode_printer_status(status)

        # ----------------------------------------------------
        # FILE D'ATTENTE
        # ----------------------------------------------------
        try:
            jobs = win32print.EnumJobs(
                hprinter,
                0,
                999,
                1
            ) or []
        except Exception:
            jobs = []

        result["queue_jobs"] = len(jobs)

        compact_jobs = []

        for job in jobs:
            compact_jobs.append({
                "JobId": job.get("JobId"),
                "Document": job.get("pDocument"),
                "User": job.get("pUserName"),
                "Status": job.get("Status"),
            })

        result["jobs"] = compact_jobs

        result["busy"] = bool(
            (status & BUSY_FLAGS)
            or result["queue_jobs"] > 0
        )

        result["error"] = bool(
            status & ERROR_FLAGS
        )

        # ----------------------------------------------------
        # CAPACITE DUPLEX DECLAREE PAR LE PILOTE
        # ----------------------------------------------------
        try:
            DC_DUPLEX = getattr(
                win32con,
                "DC_DUPLEX",
                7
            )

            duplex_cap = win32print.DeviceCapabilities(
                printer_name,
                result["port_name"] or None,
                DC_DUPLEX
            )

            result["duplex_capability"] = bool(
                duplex_cap
            )

        except Exception:
            # On reste conservateur : si on ne peut pas prouver
            # le duplex, on ne considère pas le module disponible.
            result["duplex_capability"] = False

        # ----------------------------------------------------
        # VERIFICATION DEVMODE
        # ----------------------------------------------------
        devmode = info.get("pDevMode")

        if devmode is not None:
            if duplex_edge == "long":
                wanted_duplex = win32con.DMDUP_VERTICAL
            else:
                wanted_duplex = win32con.DMDUP_HORIZONTAL

            try:
                devmode.Duplex = wanted_duplex
                devmode.Fields |= win32con.DM_DUPLEX

                # IMPORTANT :
                # on NE force PAS l'orientation ici.
                # Le pilote Evolis garde son format CR80 configuré.
                # C'est plus proche de ce qui fonctionne lorsque
                # vous imprimez manuellement le PNG téléchargé.

                try:
                    win32print.DocumentProperties(
                        0,
                        hprinter,
                        printer_name,
                        devmode,
                        devmode,
                        win32con.DM_IN_BUFFER |
                        win32con.DM_OUT_BUFFER
                    )
                except Exception:
                    # Certains pilotes de cartes ne répondent pas
                    # correctement à DocumentProperties, mais le
                    # DEVMODE reste testable.
                    pass

                result["duplex_devmode_accepted"] = (
                    getattr(
                        devmode,
                        "Duplex",
                        win32con.DMDUP_SIMPLEX
                    )
                    != win32con.DMDUP_SIMPLEX
                )

            except Exception:
                result["duplex_devmode_accepted"] = False

        # ----------------------------------------------------
        # DECISION FINALE
        # ----------------------------------------------------
        if result["error"]:
            result["message"] = (
                "Imprimante en erreur : "
                + ", ".join(result["status_labels"])
            )

        elif result["busy"]:
            result["message"] = (
                "Imprimante/module occupé. "
                f"Travaux en attente : {result['queue_jobs']}. "
                "Attendez qu'elle soit libre avant d'imprimer."
            )

        elif not result["duplex_capability"]:
            result["message"] = (
                "Le pilote Windows n'annonce PAS de capacité duplex. "
                "Impression bloquée pour éviter la sortie de deux cartes."
            )

        elif not result["duplex_devmode_accepted"]:
            result["message"] = (
                "Le pilote refuse le réglage recto-verso dans le DEVMODE. "
                "Impression bloquée."
            )

        else:
            result["ready_for_duplex"] = True
            result["message"] = (
                "Imprimante libre et pilote duplex accepté."
            )

        return result

    except Exception as exc:
        result["message"] = (
            "Impossible de contrôler l'imprimante : "
            + str(exc)
        )
        return result

    finally:
        if hprinter is not None:
            try:
                win32print.ClosePrinter(hprinter)
            except Exception:
                pass


def get_validated_duplex_devmode(
    printer_name,
    duplex_edge="short"
):
    """
    Récupère un DEVMODE validé pour CE job.
    Cette fonction suppose que inspect_printer() a déjà réussi.
    """

    import win32print
    import win32con

    hprinter = win32print.OpenPrinter(
        printer_name
    )

    try:
        info = win32print.GetPrinter(
            hprinter,
            2
        )

        devmode = info.get(
            "pDevMode"
        )

        if devmode is None:
            raise RuntimeError(
                "Le pilote ne fournit pas de DEVMODE."
            )

        if duplex_edge == "long":
            wanted_duplex = win32con.DMDUP_VERTICAL
        else:
            wanted_duplex = win32con.DMDUP_HORIZONTAL

        devmode.Duplex = wanted_duplex
        devmode.Fields |= win32con.DM_DUPLEX

        # Ne pas forcer PORTRAIT/LANDSCAPE.
        # On conserve le média/orientation CR80 du pilote Evolis.

        try:
            win32print.DocumentProperties(
                0,
                hprinter,
                printer_name,
                devmode,
                devmode,
                win32con.DM_IN_BUFFER |
                win32con.DM_OUT_BUFFER
            )
        except Exception:
            pass

        if getattr(
            devmode,
            "Duplex",
            win32con.DMDUP_SIMPLEX
        ) == win32con.DMDUP_SIMPLEX:
            raise RuntimeError(
                "Le pilote est revenu en SIMPLEX. "
                "Le travail est annulé pour ne pas imprimer deux cartes."
            )

        return devmode

    finally:
        win32print.ClosePrinter(
            hprinter
        )


def print_duplex_one_job(
    front,
    back,
    printer_name,
    rotate_back_180=False,
    bleed_percent=101.0,
    duplex_edge="short"
):
    """
    Impression de sécurité :
      - vérifie que l'imprimante/module n'est pas occupé ;
      - vérifie le duplex Windows + DEVMODE ;
      - bloque si la file contient déjà un travail ;
      - conserve le média CR80 choisi dans le driver ;
      - dessine le recto/verso sur TOUTE la surface physique ;
      - envoie les deux faces dans UN SEUL document duplex.

    Si Windows ne peut pas prouver le duplex, le code n'imprime RIEN.
    """

    if os.name != "nt":
        raise RuntimeError(
            "L'impression Evolis doit être exécutée "
            "sur le PC Windows connecté à l'imprimante."
        )

    if not printer_name:
        raise RuntimeError(
            "Aucune imprimante sélectionnée."
        )

    try:
        import win32ui
        import win32gui
        import win32con
        from PIL import ImageWin
    except ImportError:
        raise RuntimeError(
            "Installez pywin32 : pip install pywin32"
        )

    # --------------------------------------------------------
    # PRE-FLIGHT OBLIGATOIRE
    # --------------------------------------------------------
    check = inspect_printer(
        printer_name,
        duplex_edge=duplex_edge
    )

    if not check["ready_for_duplex"]:
        raise RuntimeError(
            "IMPRESSION BLOQUÉE.\n\n"
            + check["message"]
        )

    devmode = get_validated_duplex_devmode(
        printer_name,
        duplex_edge=duplex_edge
    )

    if rotate_back_180:
        back = back.rotate(
            180,
            expand=False
        )

    dc = None
    raw_hdc = None

    try:
        # IMPORTANT :
        # win32ui.CreateDC() renvoie un objet PyCDC qui ne possède PAS
        # de méthode CreateDC(...). C'était la cause de l'erreur :
        #     'PyCDC' object has no attribute 'CreateDC'
        #
        # La bonne méthode pour appliquer un PyDEVMODE spécifique est :
        #   1) créer le HDC natif avec win32gui.CreateDC(...)
        #   2) l'envelopper dans un PyCDC avec CreateDCFromHandle(...)
        raw_hdc = win32gui.CreateDC(
            "WINSPOOL",
            printer_name,
            devmode
        )

        if not raw_hdc:
            raise RuntimeError(
                "win32gui.CreateDC n'a retourné aucun contexte d'impression."
            )

        dc = win32ui.CreateDCFromHandle(
            raw_hdc
        )

    except Exception as exc:
        # Si CreateDCFromHandle n'a pas pris possession du HDC,
        # on tente de le libérer ici.
        if raw_hdc and dc is None:
            try:
                win32gui.DeleteDC(raw_hdc)
            except Exception:
                pass

        raise RuntimeError(
            "Impossible d'ouvrir le pilote Evolis "
            "avec le mode duplex validé.\n\n"
            + str(exc)
        )

    # GDI DeviceCaps physiques.
    PHYSICALWIDTH = 110
    PHYSICALHEIGHT = 111
    PHYSICALOFFSETX = 112
    PHYSICALOFFSETY = 113

    physical_w = int(
        dc.GetDeviceCaps(
            PHYSICALWIDTH
        )
    )

    physical_h = int(
        dc.GetDeviceCaps(
            PHYSICALHEIGHT
        )
    )

    offset_x = int(
        dc.GetDeviceCaps(
            PHYSICALOFFSETX
        )
    )

    offset_y = int(
        dc.GetDeviceCaps(
            PHYSICALOFFSETY
        )
    )

    printable_w = int(
        dc.GetDeviceCaps(
            win32con.HORZRES
        )
    )

    printable_h = int(
        dc.GetDeviceCaps(
            win32con.VERTRES
        )
    )

    if physical_w <= 0:
        physical_w = (
            printable_w
            + max(0, 2 * offset_x)
        )

    if physical_h <= 0:
        physical_h = (
            printable_h
            + max(0, 2 * offset_y)
        )

    if physical_w <= 0 or physical_h <= 0:
        dc.DeleteDC()
        raise RuntimeError(
            "Dimensions physiques non disponibles depuis le pilote."
        )

    # --------------------------------------------------------
    # VERIFIE QUE LE MEDIA DU PILOTE RESSEMBLE A UN CR80
    # --------------------------------------------------------
    device_ratio = (
        max(physical_w, physical_h)
        / max(1, min(physical_w, physical_h))
    )

    ratio_error = abs(
        device_ratio - CR80_RATIO
    ) / CR80_RATIO

    if ratio_error > 0.18:
        dc.DeleteDC()

        raise RuntimeError(
            "Le format média du pilote ne ressemble pas à une carte CR80.\n\n"
            f"Ratio pilote : {device_ratio:.3f}\n"
            f"Ratio CR80 attendu : {CR80_RATIO:.3f}\n\n"
            "Dans les propriétés Evolis Windows, sélectionnez "
            "le format carte CR80 avant de relancer."
        )

    def draw_full_card_page(image):
        img = image.convert("RGB")

        # Adapte automatiquement seulement si le pilote expose
        # le CR80 dans l'orientation inverse.
        image_landscape = (
            img.width >= img.height
        )

        device_landscape = (
            physical_w >= physical_h
        )

        if image_landscape != device_landscape:
            img = img.rotate(
                90,
                expand=True
            )

        zoom = max(
            1.0,
            float(bleed_percent) / 100.0
        )

        target_w = int(
            round(
                physical_w * zoom
            )
        )

        target_h = int(
            round(
                physical_h * zoom
            )
        )

        # Compensation des marges physiques du driver :
        # l'image devient réellement un "background" pleine carte.
        left = (
            -offset_x
            - ((target_w - physical_w) // 2)
        )

        top = (
            -offset_y
            - ((target_h - physical_h) // 2)
        )

        dib = ImageWin.Dib(
            img
        )

        dc.StartPage()

        dib.draw(
            dc.GetHandleOutput(),
            (
                left,
                top,
                left + target_w,
                top + target_h
            )
        )

        dc.EndPage()

    # --------------------------------------------------------
    # UN SEUL DOCUMENT :
    # PAGE 1 = RECTO
    # PAGE 2 = VERSO
    # --------------------------------------------------------
    dc.StartDoc(
        "FSAC - Carte Etudiant CR80 Duplex"
    )

    try:
        draw_full_card_page(front)
        draw_full_card_page(back)

    finally:
        try:
            dc.EndDoc()
        finally:
            try:
                dc.DeleteDC()
            except Exception:
                pass


