# Valeurs des champs éditables.
for _key, _value in {
    "field_nom": st.session_state.student_data.get("nom", ""),
    "field_prenom": st.session_state.student_data.get("prenom", ""),
    "field_filiere": st.session_state.student_data.get("filiere", ""),
    "field_numero": st.session_state.student_data.get("numero", ""),
    "field_cne": st.session_state.student_data.get("cne", ""),
    "field_cin": st.session_state.student_data.get("cin", ""),
}.items():
    if _key not in st.session_state:
        st.session_state[_key] = _value


def load_student_into_fields(student):
    st.session_state["field_nom"] = student.get("nom", "")
    st.session_state["field_prenom"] = student.get("prenom", "")
    st.session_state["field_filiere"] = student.get("filiere", "")
    st.session_state["field_numero"] = student.get("numero", "")
    st.session_state["field_cne"] = student.get("cne", "")
    st.session_state["field_cin"] = student.get("cin", "")


left, right = st.columns(
    [0.85, 1.65],
    gap="large"
)


# ============================================================
# COLONNE GAUCHE
# ============================================================

with left:

    # --------------------------------------------------------
    # CONNEXION APOGÉE
    # --------------------------------------------------------

    st.header(
        "Connexion Apogée"
    )

    auto_client = detect_oracle_client_dir()

    python_arch = get_python_architecture()

    discovered_clients = discover_oracle_clients()

    st.caption(
        f"Python détecté : {python_arch}-bit"
    )

    if discovered_clients:
        with st.expander(
            "Clients Oracle détectés"
        ):
            for _client in discovered_clients:
                _arch = oracle_client_architecture(
                    _client
                )
                st.write(
                    f"{_client} — {_arch or '?'}-bit"
                )

    with st.expander(
        "Paramètres Oracle / Instant Client",
        expanded=True
    ):

        apogee_host = st.text_input(
            "Hôte Oracle",
            value=DEFAULT_APOGEE_HOST,
            key="apogee_host"
        )

        c1, c2 = st.columns(2)

        with c1:
            apogee_port = st.number_input(
                "Port",
                min_value=1,
                max_value=65535,
                value=DEFAULT_APOGEE_PORT,
                step=1,
                key="apogee_port"
            )

        with c2:
            apogee_service = st.text_input(
                "Service",
                value=DEFAULT_APOGEE_SERVICE,
                key="apogee_service"
            )

        apogee_user = st.text_input(
            "Utilisateur Oracle",
            value="",
            key="apogee_user"
        )

        apogee_password = st.text_input(
            "Mot de passe Oracle",
            value="",
            type="password",
            key="apogee_password"
        )

        oracle_client_dir = st.text_input(
            "Oracle Instant Client (dossier contenant oci.dll)",
            value=auto_client,
            placeholder=r"Ex. C:\oracle\instantclient_19_24 (même architecture que Python)",
            key="oracle_client_dir"
        )

        image_dir = st.text_input(
            "Dossier des photos étudiants",
            value=DEFAULT_IMAGE_DIR,
            key="student_image_dir"
        )

        st.caption(
            "Cette base Oracle nécessite Thick mode. "
            "Le programme initialise Instant Client AVANT la connexion."
        )

        if st.button(
            "🔌 Tester la connexion Apogée",
            use_container_width=True
        ):
            pool = None

            try:
                pool = create_apogee_pool(
                    host=apogee_host,
                    port=int(apogee_port),
                    service=apogee_service,
                    user=apogee_user,
                    password=apogee_password,
                    client_lib_dir=oracle_client_dir
                )

                st.success(
                    "Connexion Apogée OK — Thick mode actif."
                )

            except Exception as error:
                st.error(
                    str(error)
                )

            finally:
                close_apogee_pool(
                    pool
                )

    # --------------------------------------------------------
    # RECHERCHE
    # --------------------------------------------------------

    st.header(
        "Rechercher un étudiant"
    )

    ident_value = st.text_input(
        "Code Apogée ou CIN",
        placeholder="Ex. 25005151 ou BK756677",
        key="student_search_ident"
    )

    if ident_value.strip():
        if ident_value.strip().isdigit():
            st.caption(
                "Type détecté : Code Apogée"
            )
        else:
            st.caption(
                "Type détecté : CIN"
            )

    if st.button(
        "🔎 Rechercher dans Apogée",
        type="primary",
        use_container_width=True
    ):

        pool = None

        try:
            pool = create_apogee_pool(
                host=apogee_host,
                port=int(apogee_port),
                service=apogee_service,
                user=apogee_user,
                password=apogee_password,
                client_lib_dir=oracle_client_dir
            )

            found = fetch_student_from_apogee(
                pool=pool,
                ident_value=ident_value,
                image_dir=image_dir
            )

            st.session_state.student_data = found

            load_student_into_fields(
                found
            )

            st.session_state["student_last_found"] = (
                f"{found.get('nom', '')} "
                f"{found.get('prenom', '')}"
            ).strip()

            st.rerun()

        except Exception as error:
            st.error(
                str(error)
            )

        finally:
            close_apogee_pool(
                pool
            )

    if st.session_state.get(
        "student_last_found"
    ):
        st.success(
            "Étudiant chargé : "
            + st.session_state["student_last_found"]
        )

    # --------------------------------------------------------
    # CHAMPS DEMANDÉS
    # --------------------------------------------------------

    st.header(
        "Informations étudiant"
    )

    nom = st.text_input(
        "Nom",
        key="field_nom"
    )

    prenom = st.text_input(
        "Prénom",
        key="field_prenom"
    )

    filiere = st.text_input(
        "Filière / Étape",
        key="field_filiere"
    )

    numero = st.text_input(
        "N° étudiant / Code Apogée",
        key="field_numero"
    )

    cne = st.text_input(
        "CNE",
        key="field_cne"
    )

    cin = st.text_input(
        "CIN",
        key="field_cin"
    )

    data = st.session_state.student_data

    # --------------------------------------------------------
    # PHOTO PAR CIN MAJUSCULE
    # --------------------------------------------------------

    portrait = data.get(
        "photo"
    )

    photo_path = data.get(
        "photo_path"
    )

    if portrait is not None:
        st.success(
            "Photo trouvée automatiquement."
        )

        if photo_path:
            st.caption(
                "Photo : "
                + str(photo_path)
            )

        st.image(
            portrait,
            width=120
        )

    elif cin.strip():
        st.warning(
            "Aucune photo trouvée dans "
            + image_dir
            + " pour le CIN "
            + cin.strip().upper()
        )

    uploaded_photo = st.file_uploader(
        "Photo manuelle (secours)",
        type=[
            "png",
            "jpg",
            "jpeg",
            "bmp",
            "webp"
        ]
    )

    if uploaded_photo is not None:
        portrait = Image.open(
            uploaded_photo
        ).convert("RGB")

        st.session_state.student_data["photo"] = portrait
        st.session_state.student_data["photo_path"] = "Upload manuel"

    # Toute correction manuelle des champs est immédiatement utilisée
    # dans le rendu de la carte.
    st.session_state.student_data.update({
        "nom": nom,
        "prenom": prenom,
        "filiere": filiere,
        "numero": numero,
        "cne": cne,
        "cin": cin,
        "photo": portrait,
    })

    st.divider()

    # --------------------------------------------------------
    # IMPRIMANTES
    # --------------------------------------------------------

    st.header(
        "Impression Evolis"
    )

    if os.name != "nt":
        st.warning(
            "Le programme ne détecte les imprimantes que "
            "sur le PC Windows où Streamlit est exécuté."
        )

    if st.button(
        "🔄 Actualiser les imprimantes",
        use_container_width=True
    ):
        st.rerun()

    printers = list_windows_printers()

    default_printer = get_default_windows_printer()

    selected_printer = None

    if printers:

        # Si l'imprimante par défaut existe dans la liste,
        # on la sélectionne par défaut sauf s'il existe une Evolis.
        index = 0

        evolis_indexes = [
            i
            for i, p in enumerate(printers)
            if "evolis" in p.lower()
        ]

        if evolis_indexes:
            index = evolis_indexes[0]

        elif default_printer in printers:
            index = printers.index(
                default_printer
            )

        selected_printer = st.selectbox(
            "Imprimante détectée",
            printers,
            index=index
        )

        st.success(
            f"{len(printers)} imprimante(s) détectée(s)."
        )

    else:
        st.warning(
            "Aucune imprimante détectée automatiquement."
        )

    manual_printer = st.text_input(
        "Nom manuel de l'imprimante",
        placeholder="Ex. Evolis Primacy 2",
        help=(
            "Utilisez ce champ si votre imprimante existe dans Windows "
            "mais n'apparaît pas dans la liste."
        )
    )

    printer = (
        manual_printer.strip()
        if manual_printer.strip()
        else selected_printer
    )

    if default_printer:
        st.caption(
            "Imprimante Windows par défaut : "
            + default_printer
        )

    with st.expander(
        "Diagnostic imprimantes"
    ):
        st.write(
            "Système :",
            platform.platform()
        )

        st.write(
            "Windows :",
            os.name == "nt"
        )

        try:
            import win32print
            st.success(
                "pywin32 / win32print disponible."
            )
        except Exception as e:
            st.error(
                "pywin32 non disponible. "
                "Installez-le avec : pip install pywin32"
            )

        st.write(
            "Imprimantes détectées :",
            printers
        )

    rotate_back = st.checkbox(
        "Tourner le verso de 180°",
        value=False,
        help=(
            "À activer seulement si le verso sort à l'envers "
            "avec votre configuration Evolis."
        )
    )


    duplex_edge_label = st.selectbox(
        "Retournement recto-verso",
        [
            "Bord court — recommandé pour CR80 paysage",
            "Bord long"
        ],
        index=0,
        help=(
            "Si le verso est mal orienté, essayez l'autre mode "
            "ou utilisez l'option 180°."
        )
    )

    duplex_edge = (
        "long"
        if duplex_edge_label.startswith("Bord long")
        else "short"
    )

    bleed_percent = st.slider(
        "Remplissage de la carte (%)",
        min_value=100.0,
        max_value=104.0,
        value=101.0,
        step=0.5,
        help=(
            "101 % fait légèrement dépasser l'image des bords afin "
            "d'obtenir le même effet pleine carte que l'impression "
            "manuelle du PNG téléchargé."
        )
    )


    st.subheader(
        "État imprimante / module duplex"
    )

    printer_check = None

    if printer and os.name == "nt":
        printer_check = inspect_printer(
            printer,
            duplex_edge=duplex_edge
        )

        if printer_check["ready_for_duplex"]:
            st.success(
                "✅ PRÊTE — imprimante libre + duplex accepté"
            )
        elif printer_check["busy"]:
            st.warning(
                "⏳ OCCUPÉE — "
                + printer_check["message"]
            )
        else:
            st.error(
                "⛔ NON PRÊTE — "
                + printer_check["message"]
            )

        with st.expander(
            "Détails du contrôle avant impression"
        ):
            st.write(
                "Imprimante :",
                printer_check["printer"]
            )
            st.write(
                "Pilote :",
                printer_check["driver_name"]
            )
            st.write(
                "Port :",
                printer_check["port_name"]
            )
            st.write(
                "État Windows :",
                printer_check["status_labels"]
            )
            st.write(
                "Travaux dans la file :",
                printer_check["queue_jobs"]
            )
            st.write(
                "Duplex annoncé par Windows :",
                printer_check["duplex_capability"]
            )
            st.write(
                "Duplex accepté par le DEVMODE :",
                printer_check["duplex_devmode_accepted"]
            )

            if printer_check["jobs"]:
                st.write(
                    "Travaux :",
                    printer_check["jobs"]
                )

    elif printer:
        st.warning(
            "Le contrôle d'état complet nécessite Windows."
        )


# ============================================================
# COLONNE DROITE
# ============================================================

with right:

    front = create_front_card(
        nom=nom,
        prenom=prenom,
        filiere=filiere,
        numero=numero,
        cne=cne,
        cin=cin,
        portrait_img=portrait
    )

    back = create_back_card()

    tab_front, tab_back = st.tabs(
        [
            "RECTO",
            "VERSO — QR CODE"
        ]
    )


    with tab_front:

        st.subheader(
            "Aperçu du recto"
        )

        st.caption(
            "CR80 — 85,60 × 53,98 mm — 300 dpi"
        )

        st.image(
            front,
            use_container_width=True
        )

        st.caption(
            "Le code-barres est décoratif et identique "
            "sur toutes les cartes."
        )


    with tab_back:

        st.subheader(
            "Aperçu du verso"
        )

        st.caption(
            "QR Code fonctionnel vers le site officiel de la FSAC"
        )

        st.image(
            back,
            use_container_width=True
        )

        st.success(
            "QR Code : "
            + FSAC_URL
        )


    download1, download2 = st.columns(2)

    with download1:

        st.download_button(
            "⬇️ Télécharger RECTO",
            data=png_bytes(front),
            file_name=f"carte_{numero}_recto.png",
            mime="image/png",
            use_container_width=True
        )

    with download2:

        st.download_button(
            "⬇️ Télécharger VERSO",
            data=png_bytes(back),
            file_name=f"carte_{numero}_verso.png",
            mime="image/png",
            use_container_width=True
        )


    st.divider()

    st.subheader(
        "Impression recto-verso"
    )

    if printer:
        st.info(
            "Imprimante sélectionnée : "
            + printer
        )
    else:
        st.warning(
            "Sélectionnez une imprimante dans la partie gauche."
        )

    can_print_duplex = bool(
        printer
        and os.name == "nt"
        and printer_check
        and printer_check["ready_for_duplex"]
    )

    if st.button(
        "🖨️ IMPRIMER RECTO + VERSO",
        type="primary",
        use_container_width=True,
        disabled=not can_print_duplex
    ):

        if not printer:

            st.warning(
                "Aucune imprimante sélectionnée."
            )

        else:

            try:
                print_duplex_one_job(
                    front=front,
                    back=back,
                    printer_name=printer,
                    rotate_back_180=rotate_back,
                    bleed_percent=bleed_percent,
                    duplex_edge=duplex_edge
                )

                st.success(
                    "Recto + verso envoyés dans un seul travail "
                    "d'impression vers : "
                    + printer
                )

            except Exception as error:

                st.error(
                    str(error)
                )

    st.info(
        "Sécurité activée : le bouton reste désactivé si l'imprimante "
        "est occupée, si la file contient déjà un travail, si Windows "
        "ne déclare pas le duplex ou si le DEVMODE refuse le duplex. "
        "Le contexte d'impression est maintenant créé avec "
        "win32gui.CreateDC + CreateDCFromHandle afin d'appliquer "
        "correctement le DEVMODE Evolis."
    )
